css:
body{margin:0;background:#0D0D0E;font-family:'Onest',system-ui,sans-serif;color:#F4F3EF}
a{color:#F4F3EF;text-decoration:none}a:hover{text-decoration:underline;text-underline-offset:5px}
.navlink{font-size:15px;font-weight:500;color:#F4F3EF;white-space:nowrap;opacity:.82}
.navlink:hover{opacity:1}
.pill{align-self:flex-start;display:inline-flex;align-items:center;height:34px;padding:0 16px;border:1.5px solid rgba(244,243,239,.9);border-radius:18px;font-size:15px;font-weight:500;white-space:nowrap}
.dir{font-size:clamp(17px,1.45vw,21px);font-weight:500;white-space:nowrap}
.sep{opacity:.5;margin:0 10px}
.media{position:absolute;inset:0;background:linear-gradient(160deg,#2A2A2B 0%,#1A1A1B 55%,#121213 100%)}
.cap{font-size:13px;letter-spacing:.02em;color:rgba(244,243,239,.62)}
.glass{display:inline-flex;align-items:center;gap:12px;height:48px;padding:0 18px;border-radius:4px;background:rgba(12,12,13,.42);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border:1px solid rgba(244,243,239,.38);font-size:16px;font-weight:500;color:#F4F3EF;white-space:nowrap}
.img1,.img2,.img3{background-size:cover;background-position:70% 50%;background-repeat:no-repeat;background-color:#141415}
.img1{background-image:url(/assets/card1.webp)}
.img2{background-image:url(/assets/card2.webp)}
.img3{background-image:url(/assets/card3.webp)}
.eci{position:absolute;inset:0;background-size:cover;background-position:50% 50%;background-repeat:no-repeat}
.eci1{background-image:url(/assets/etalon_case1.webp)}
.eci2{background-image:url(/assets/etalon_case2.webp)}
.eci3{background-image:url(/assets/etalon_case3.webp)}
.xb{display:flex;flex-direction:column;justify-content:space-between;gap:5vh;padding:30px;border:1px solid #2C2C2E;border-radius:14px;background:#121213;color:#F4F3EF;transition:border-color .3s,background .3s,transform .4s cubic-bezier(.2,.7,0,1)}
.xb:hover{text-decoration:none;border-color:rgba(244,243,239,.5);background:#171718}
.xb-c{background:linear-gradient(135deg,#5A2E18 0%,#2A1710 55%,#141211 100%);border-color:rgba(241,158,101,.35)}
.xb-c:hover{background:linear-gradient(135deg,#6B3820 0%,#331C12 55%,#161312 100%);border-color:rgba(241,158,101,.7)}
.xb-l{background:#F4F3EF;border-color:#F4F3EF;color:#0D0D0E}
.xb-l:hover{background:#FFFFFF;border-color:#FFFFFF}
.xb-sq{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid currentColor;border-radius:4px;opacity:.7;transition:background .25s,color .25s,opacity .25s}
.xb:hover .xb-sq{opacity:1;background:#F4F3EF;color:#0D0D0E;border-color:#F4F3EF}
.xb-l:hover .xb-sq{background:#0D0D0E;color:#F4F3EF;border-color:#0D0D0E}
.xs{display:flex;flex-direction:column;justify-content:flex-start;gap:14vh;padding:28px;border:1px solid #2C2C2E;border-radius:12px;background:#111112;color:#F4F3EF;transition:border-color .3s,background .3s}
.xs:hover{text-decoration:none;border-color:rgba(244,243,239,.5);background:#161617}
.xs-sq{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid rgba(244,243,239,.45);border-radius:4px;transition:background .25s,color .25s}
.xs:hover .xs-sq{background:#F4F3EF;color:#0D0D0E}
.asBg{background-image:url(/assets/foundry_bw.webp);background-position:56% 45%;filter:grayscale(1) contrast(1.05) brightness(.82)}
.asCard{display:flex;flex-direction:column;flex:1;min-height:0;border:1px solid #2C2C2E;border-radius:14px;background:#121213;color:#F4F3EF;overflow:hidden}
.cimg{position:absolute;inset:0;background-size:cover;background-position:50% 50%;background-repeat:no-repeat}
.cimg1{background-image:url(/assets/case1.webp)}
.cimg2{background-image:url(/assets/case2.webp)}
.cimg3{background-image:url(/assets/case3.webp)}
@keyframes ring{0%{transform:scale(1);opacity:.7}100%{transform:scale(2.6);opacity:0}}
@keyframes flow{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
.flow{stroke-dasharray:.035 .965;animation:flow 2.8s linear infinite}
.ring{transform-box:fill-box;transform-origin:center;animation:ring 2.2s ease-out infinite}
.ctaA{flex-shrink:0;display:inline-flex;align-items:center;gap:14px;height:56px;padding:0 26px;border:1px solid rgba(244,243,239,.55);border-radius:4px;color:#F4F3EF;font-size:17px;font-weight:500;white-space:nowrap;transition:background .25s,color .25s,border-color .25s}
.ctaA:hover{background:#F4F3EF;color:#0D0D0E;border-color:#F4F3EF;text-decoration:none}
.ctaB{flex-shrink:0;display:inline-flex;align-items:stretch;height:56px;border:1px solid rgba(244,243,239,.55);border-radius:4px;overflow:hidden;color:#F4F3EF;font-size:17px;font-weight:500;white-space:nowrap;transition:border-color .25s}
.ctaB-t{display:flex;align-items:center;padding:0 24px}
.ctaB-sq{display:flex;align-items:center;justify-content:center;width:56px;background:#F4F3EF;color:#0D0D0E;transition:width .35s cubic-bezier(.2,.7,0,1)}
.ctaB:hover{border-color:#F4F3EF;text-decoration:none}
.ctaB:hover .ctaB-sq{width:72px}
.ctaC{flex-shrink:0;display:inline-flex;align-items:center;gap:16px;min-height:48px;color:#F4F3EF;font-size:19px;font-weight:500;white-space:nowrap}
.ctaC-t{padding-bottom:6px;background:linear-gradient(#F4F3EF,#F4F3EF) 0 100%/100% 1px no-repeat;transition:background-size .35s}
.ctaC-sq{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid rgba(244,243,239,.55);border-radius:3px;transition:background .25s,color .25s}
.ctaC:hover{text-decoration:none}
.ctaC:hover .ctaC-sq{background:#F4F3EF;color:#0D0D0E}
.ctaC:hover .ctaC-t{background-size:0 1px;background-position:100% 100%}
.glass:hover{background:rgba(244,243,239,.16);text-decoration:none}
.fld{display:flex;flex-direction:column;gap:6px;min-width:0}
.fld-l{font-size:13px;letter-spacing:.02em;color:rgba(244,243,239,.62)}
.inp{width:100%;box-sizing:border-box;height:52px;background:transparent;border:0;border-bottom:1px solid rgba(244,243,239,.3);border-radius:0;color:#F4F3EF;font:400 19px 'Onest',sans-serif;padding:0;outline:none;transition:border-color .25s}
.inp::placeholder{color:rgba(244,243,239,.28)}
.inp:hover{border-bottom-color:rgba(244,243,239,.6)}
.inp:focus{border-bottom-color:#F4F3EF}
.inp.bad{border-bottom-color:#FF6B6B}
textarea.inp{height:auto;min-height:92px;padding-top:14px;resize:vertical;line-height:1.45}
.err{font-size:13px;color:#FF6B6B;min-height:18px}
.chip{height:40px;padding:0 16px;border:1px solid rgba(244,243,239,.3);border-radius:4px;background:transparent;color:#F4F3EF;font:500 15px 'Onest',sans-serif;cursor:pointer;white-space:nowrap;transition:background .25s,color .25s,border-color .25s}
.chip:hover{border-color:#F4F3EF}
.chip.on{background:#F4F3EF;color:#0D0D0E;border-color:#F4F3EF}
.chip:focus-visible,.inp:focus-visible,.cbx:focus-visible{outline:2px solid #F4F3EF;outline-offset:3px}
.cbx{flex-shrink:0;width:22px;height:22px;border-radius:3px;border:1px solid rgba(244,243,239,.55);background:transparent;color:#0D0D0E;display:flex;align-items:center;justify-content:center;padding:0;cursor:pointer}
.cbx.on{background:#F4F3EF;border-color:#F4F3EF}
.cbx.bad{border-color:#FF6B6B}
.fh{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:rgba(244,243,239,.45);margin:0 0 18px}
.fl{display:block;font-size:15px;line-height:1.3;color:rgba(244,243,239,.78);padding:6px 0}
.fl:hover{color:#F4F3EF}
.step{display:grid;grid-template-columns:44px minmax(0,1fr);gap:4px 12px;padding:18px 0;border-top:1px solid #2C2C2E}
.step b{font-weight:500;font-size:17px}
.step span{grid-column:2;font-size:15px;color:rgba(244,243,239,.62);line-height:1.4}
.hbtn{display:inline-flex;align-items:center;gap:10px;height:40px;padding:0 16px;border:1px solid rgba(244,243,239,.55);border-radius:4px;color:#F4F3EF;font-size:15px;font-weight:500;white-space:nowrap;transition:background .25s,color .25s,border-color .25s}
.hbtn:hover{background:#F4F3EF;color:#0D0D0E;border-color:#F4F3EF;text-decoration:none}
.hsq{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;box-sizing:border-box;border-radius:4px;border:1px solid rgba(244,243,239,.55);background:transparent;color:#F4F3EF;transition:background .25s,color .25s,border-color .25s}
.hsq:hover{background:#F4F3EF;color:#0D0D0E;border-color:#F4F3EF;text-decoration:none}
.hex{display:inline-flex;align-items:stretch;height:40px;border:1px solid rgba(244,243,239,.55);border-radius:4px;overflow:hidden;color:#F4F3EF;font-size:15px;font-weight:500;white-space:nowrap}
.hex-t{display:flex;align-items:center;max-width:0;opacity:0;padding:0;transition:max-width .45s cubic-bezier(.2,.7,0,1),opacity .3s,padding .45s cubic-bezier(.2,.7,0,1)}
.hex-i{display:flex;align-items:center;justify-content:center;width:38px;background:#F4F3EF;color:#0D0D0E}
.hex:hover,.hex:focus-visible{text-decoration:none;border-color:#F4F3EF}
.hex:hover .hex-t,.hex:focus-visible .hex-t{max-width:220px;opacity:1;padding:0 16px}
.crumb{font-size:14px;color:rgba(244,243,239,.55)}
.crumb a{color:rgba(244,243,239,.72)}
.btnF{display:inline-flex;align-items:center;gap:14px;height:56px;padding:0 26px;border-radius:4px;background:#F4F3EF;color:#0D0D0E;font-size:17px;font-weight:500;white-space:nowrap;border:1px solid #F4F3EF;transition:background .25s,color .25s}
.btnF:hover{background:transparent;color:#F4F3EF;text-decoration:none}
.tag{display:inline-flex;align-items:center;height:32px;padding:0 12px;border:1px solid rgba(244,243,239,.3);border-radius:4px;font-size:14px;color:rgba(244,243,239,.85);white-space:nowrap}
.eyebrow{font-size:14px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:rgba(244,243,239,.62)}
.h2{margin:0;font-size:clamp(34px,3.4vw,60px);line-height:1.02;font-weight:500;letter-spacing:-.035em}
.lead{margin:0;font-size:clamp(17px,1.35vw,21px);line-height:1.5;color:rgba(244,243,239,.72)}
.aida{display:inline-flex;align-items:center;gap:8px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:rgba(244,243,239,.4)}
.aida b{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border:1px solid rgba(244,243,239,.3);border-radius:3px;font-weight:500;color:rgba(244,243,239,.7)}
.ph{position:relative;border-radius:10px;overflow:hidden;background:linear-gradient(160deg,#2A2A2B 0%,#1A1A1B 55%,#121213 100%)}
.cu{background:linear-gradient(100deg,#FFF1E2 0%,#FFD190 30%,#F19E65 60%,#B05A33 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent}
@keyframes grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes pop{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.bar{transform-origin:left center;animation:grow 1.6s .4s cubic-bezier(.2,.7,0,1) both}
.mk{animation:pop .7s both}
@media (prefers-reduced-motion: reduce){.bar,.mk{animation:none}}
.abp{position:absolute;inset:0;background-size:cover;background-position:50% 35%;background-repeat:no-repeat;transition:transform .8s cubic-bezier(.2,.7,0,1)}
.ab1{background-image:url(/assets/ab1.webp)}
.ab2{background-image:url(/assets/ab2.webp)}
.ab3{background-image:url(/assets/ab3.webp)}
.ab4{background-image:url(/assets/ab4.webp)}
.abt:hover .abp{transform:scale(1.04)}
.sv1{background-image:url(/assets/etalon_svc1.webp);background-position:70% 50%}
.sv2{background-image:url(/assets/etalon_svc2.webp);background-position:70% 50%}
.sv3{background-image:url(/assets/etalon_svc3.webp);background-position:70% 50%}
.svbg{position:absolute;inset:0;background-size:cover;background-repeat:no-repeat}
.pill{display:inline-flex;align-items:center;height:34px;padding:0 14px;border:1px solid rgba(244,243,239,.75);border-radius:17px;font-size:15px;white-space:nowrap;color:#F4F3EF;background:rgba(12,12,13,.25);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.line{display:block;overflow:hidden;padding-bottom:.06em}
.line>span{display:block;animation:rise 1.1s cubic-bezier(.2,.7,0,1) both}
.wd{display:inline-block;overflow:hidden;vertical-align:top;padding-bottom:.08em;margin-bottom:-.08em}
.wd>span{display:inline-block;animation:rise 1.05s cubic-bezier(.2,.7,0,1) both}
.up{animation:up .9s cubic-bezier(.2,.7,0,1) both}
@keyframes up{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
.vin{animation:fade 1.8s .2s both}
@keyframes rise{from{transform:translateY(105%)}to{transform:translateY(0)}}
@keyframes fade{from{opacity:0}to{opacity:1}}
.fadein{animation:fade 1.2s .9s both}
@media (prefers-reduced-motion: reduce){.line>span,.fadein,.wd>span,.up,.vin{animation:none}}

.qgrid{position:absolute;inset:0;background-image:linear-gradient(rgba(244,243,239,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(244,243,239,.045) 1px,transparent 1px);background-size:64px 64px;-webkit-mask-image:radial-gradient(ellipse 80% 70% at 70% 45%,#000 30%,transparent 100%);mask-image:radial-gradient(ellipse 80% 70% at 70% 45%,#000 30%,transparent 100%)}
.qglow{position:absolute;right:-10vw;top:-10vh;width:70vw;height:90vh;background:radial-gradient(closest-side,rgba(241,158,101,.16),rgba(241,158,101,0));pointer-events:none}
.qreg{position:relative;border:1px solid #2C2C2E;border-radius:16px;background:rgba(18,18,19,.86);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);padding:28px;display:flex;flex-direction:column;gap:22px;box-shadow:0 30px 80px rgba(0,0,0,.45)}
.qtype{display:inline-block;overflow:hidden;white-space:nowrap;vertical-align:bottom;font-variant-numeric:tabular-nums;width:0;animation:qtype 9s steps(26) infinite}
.qcar{display:inline-block;width:2px;height:1.1em;background:#F19E65;vertical-align:-3px;margin-left:2px;animation:qblink .8s steps(1) infinite}
.qok{animation:qok 9s cubic-bezier(.2,.7,0,1) infinite}
.qok2{animation:qok2 9s cubic-bezier(.2,.7,0,1) infinite}
.qseal{position:absolute;right:-64px;top:-84px;width:150px;height:150px;animation:qspin 30s linear infinite;opacity:.9}
@keyframes qtype{0%,6%{width:0}40%,92%{width:26ch}100%{width:0}}
@keyframes qblink{50%{opacity:0}}
@keyframes qok{0%,44%{opacity:0;transform:translateY(10px)}52%,92%{opacity:1;transform:none}100%{opacity:0}}
@keyframes qok2{0%,52%{opacity:0;transform:translateY(10px)}60%,92%{opacity:1;transform:none}100%{opacity:0}}
@keyframes qspin{to{transform:rotate(360deg)}}
.qBg{background-image:url(/assets/quality_about_bw.webp);background-size:cover;background-position:50% 40%;filter:grayscale(1) contrast(1.05) brightness(.85)}
.qsv{position:absolute;inset:0}
.qsv1{background-image:url(/assets/quality_svc1.webp);background-size:cover;background-position:60% 50%}
.qsv2{background-image:url(/assets/quality_svc2.webp);background-size:cover;background-position:60% 50%}
.qsv3{background-image:url(/assets/quality_svc3.webp);background-size:cover;background-position:60% 50%}
.qsv4{background-image:url(/assets/quality_svc4.webp);background-size:cover;background-position:60% 50%}
.qill{position:absolute;right:5vw;top:50%;transform:translateY(-50%);width:clamp(260px,30vw,480px);aspect-ratio:1;opacity:.9;pointer-events:none}
@media (prefers-reduced-motion: reduce){.qtype{animation:none;width:26ch}.qok,.qok2{animation:none}.qseal{animation:none}.qcar{display:none}}
